mapper.update:
UPDATE tdm36_role_report
   SET tdm36_board_open_date   = #{boardOpenDate}
     , tdm36_allc_std_date     = #{allcStdDate}
     , tdm36_report_date       = #{reportDate}
     , tdm36_board_open_loc    = #{boardOpenLoc}
     , tdm36_memb_tot_cnt      = #{membTotCnt}
     , tdm36_memb_attend_cnt   = #{membAttendCnt}
     , tdm36_board_open_agenda = #{boardOpenAgenda}
     , tdm36_memb_yes_nm       = #{membYesName}
     , tdm36_upd_nm            = #{updName}
     , tdm36_upd_date          = f_sysdate()
 WHERE tdm36_role_report_id = #{roleReportId}
   AND tdm36_company_id     = #{companyId}

